test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});

test('does not lose a cent to float error', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 3 }]), ['Mug: 59.97', 'Total: 59.97']);
});

test('prints refund lines with a single leading minus', () => {
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]), ['Refund: -0.50', 'Total: -0.50']);
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-19.99', qty: 1 }]), ['Refund: -19.99', 'Total: -19.99']);
});

test('applies a percent discount to the order', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Mug', price: '19.99', qty: 3 }], 10),
    ['Mug: 59.97', 'Discount: -6.00', 'Total: 53.97'],
  );
});

